def pin(data):
    return {"bytes":len(data),"sha256":hashlib.sha256(data).hexdigest(),"git_blob":hashlib.sha1(b"blob "+str(len(data)).encode()+b"\0"+data).hexdigest()}
def inspect(p):
    s=p.lstat();assert stat.S_ISREG(s.st_mode) and not p.is_symlink()
    return {**pin(p.read_bytes()),"mode":oct(stat.S_IMODE(s.st_mode)),"mtime_ns":s.st_mtime_ns}
