rows=json.loads("[{\"path\":\"install.py\",\"git_blob\":\"0a1d7ca0ecbf920d510b6f12859a3200569c991a\",\"bytes\":11448,\"uploaded\":true,\"exact_readback\":true,\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Install the exact original eight-member offline package into a new Mac directory.\\\"\\\"\\\"\\nimport argparse\\nimport hashlib\\nimport io\\nimport json\\nimport os\\nfrom pathlib import Path, PurePosixPath\\nimport re\\nimport shlex\\nimport shutil\\nimport stat\\nimport subprocess\\nimport sys\\nimport zipfile\\n\\nARCHIVE = {\\n    \\\"bytes\\\": 53535,\\n    \\\"sha256\\\": \\\"a86d823d70be98d08fd804ce9d8bccdb071b586adf5c30c0784a96a5db2a03e9\\\",\\n    \\\"git_blob\\\": \\\"ae0f3ed4e067fd527b1db7e103270419242db0c2\\\",\\n}\\nMEMBERS = (\\n    \\\"AI-DISCLOSURE.md\\\", \\\"MANIFEST.sha256\\\", \\\"SOURCE-PROVENANCE.json\\\",\\n    \\\"START-HERE.html\\\", \\\"courses/edit-distance-explorer.html\\\",\\n    \\\"courses/edit-distance.json\\\", \\\"courses/edit-distance.md\\\", \\\"demo.html\\\",\\n)\\nSOURCES = (\\\"install.py\\\", \\\"launch.py\\\", \\\"launch.command.in\\\", \\\"README.md\\\", \\\"INPUTS.json\\\")\\nCAP = 2 * 1024 * 1024\\nMIN_DISK = 256 * 1024 * 1024\\nMIN_MEMORY = 2 * 1024 ** 3\\n\\n\\ndef pin(data):\\n    return {\\n        \\\"bytes\\\": len(data),\\n        \\\"sha256\\\": hashlib.sha256(data).hexdigest(),\\n        \\\"git_blob\\\": hashlib.sha1(b\\\"blob \\\" + str(len(data)).encode(\\\"ascii\\\") + b\\\"\\\\0\\\" + data).hexdigest(),\\n    }\\n\\n\\ndef read_regular(path, limit=1024 * 1024):\\n    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)\\n    with os.fdopen(fd, \\\"rb\\\") as stream:\\n        before = os.fstat(stream.fileno())\\n        if not stat.S_ISREG(before.st_mode) or before.st_size > limit:\\n            raise ValueError(\\\"Expected a bounded regular file: \\\" + str(path))\\n        data = stream.read(limit + 1)\\n        after = os.fstat(stream.fileno())\\n    fields = (\\\"st_dev\\\", \\\"st_ino\\\", \\\"st_size\\\", \\\"st_mtime_ns\\\", \\\"st_ctime_ns\\\")\\n    if len(data) > limit or len(data) != before.st_size or any(\\n        getattr(before, key) != getattr(after, key) for key in fields\\n    ):\\n        raise ValueError(\\\"File changed while reading: \\\" + str(path))\\n    return data\\n\\n\\ndef owned_bytes(root):\\n    total = 0\\n    for path in root.rglob(\\\"*\\\"):\\n        if path.is_symlink():\\n            raise ValueError(\\\"Unexpected link in the owned preparation directory: \\\" + str(path))\\n        if path.is_file():\\n            total += path.stat().st_size\\n        elif not path.is_dir():\\n            raise ValueError(\\\"Unexpected nonregular owned entry: \\\" + str(path))\\n    return total\\n\\n\\ndef admission(owned, destination):\\n    disk = min(shutil.disk_usage(owned).free, shutil.disk_usage(destination.parent).free)\\n    report = subprocess.run(\\n        [\\\"/usr/bin/vm_stat\\\"], capture_output=True, text=True, check=True, timeout=5\\n    ).stdout\\n    page = int(re.search(r\\\"page size of (\\\\d+) bytes\\\", report).group(1))\\n    memory = sum(int(re.search(r\\\"^\\\" + re.escape(name) + r\\\":\\\\s+(\\\\d+)\\\", report, re.M).group(1))\\n                 for name in (\\\"Pages free\\\", \\\"Pages inactive\\\", \\\"Pages speculative\\\")) * page\\n    if disk < MIN_DISK or memory < MIN_MEMORY:\\n        raise ValueError(\\\"Native admission floor not met: disk=%d memory=%d\\\" % (disk, memory))\\n    return {\\\"free_disk\\\": disk, \\\"conservative_memory\\\": memory,\\n            \\\"minimum_free_disk\\\": MIN_DISK, \\\"minimum_conservative_memory\\\": MIN_MEMORY}\\n\\n\\ndef write_new(path, data, mode):\\n    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)\\n    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, mode)\\n    with os.fdopen(fd, \\\"wb\\\") as stream:\\n        stream.write(data)\\n        stream.flush()\\n        os.fsync(stream.fileno())\\n    if read_regular(path) != data:\\n        raise RuntimeError(\\\"Installed readback differed: \\\" + str(path))\\n    if stat.S_IMODE(path.stat().st_mode) != mode:\\n        raise RuntimeError(\\\"Installed mode differed: \\\" + str(path))\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=\\\"Install the unchanged offline edit-distance package.\\\")\\n    parser.add_argument(\\\"--archive\\\", required=True, help=\\\"Exact original qualified ZIP.\\\")\\n    parser.add_argument(\\\"--destination\\\", required=True, help=\\\"New absolute installation directory.\\\")\\n    parser.add_argument(\\\"--owned-root\\\", required=True, help=\\\"Existing absolute owned source/archive directory.\\\")\\n    args = parser.parse_args()\\n    if sys.platform != \\\"darwin\\\":\\n        raise ValueError(\\\"This installer uses the existing macOS runtime and file opener\\\")\\n    if not args.destination or not args.owned_root:\\n        raise ValueError(\\\"Destination and owned root must be nonempty\\\")\\n    destination = Path(args.destination)\\n    owned = Path(args.owned_root)\\n    archive_path = Path(args.archive)\\n    source = Path(os.path.abspath(__file__)).parent\\n    if not destination.is_absolute() or not owned.is_absolute() or not archive_path.is_absolute():\\n        raise ValueError(\\\"Use absolute archive, destination and owned-root paths\\\")\\n    if os.path.lexists(destination):\\n        raise FileExistsError(\\\"Destination already exists: \\\" + str(destination))\\n    if owned.is_symlink() or not owned.is_dir() or destination.parent.is_symlink() or not destination.parent.is_dir():\\n        raise ValueError(\\\"Expected existing real source and destination-parent directories\\\")\\n    if destination == owned or owned in destination.parents:\\n        raise ValueError(\\\"Use a new destination outside the owned preparation directory\\\")\\n    if owned not in source.parents or owned not in archive_path.parents:\\n        raise ValueError(\\\"Source and archive must remain inside the declared owned root\\\")\\n    if source.is_symlink() or set(path.name for path in source.iterdir()) != set(SOURCES):\\n        raise ValueError(\\\"Source input directory must contain exactly the five declared files\\\")\\n    source_data = {name: read_regular(source / name, 262144) for name in SOURCES}\\n    inputs = json.loads(source_data[\\\"INPUTS.json\\\"])\\n    if not isinstance(inputs, dict) or inputs.get(\\\"schema\\\") != \\\"recall-edit-distance-local-inputs/v1\\\" or inputs.get(\\\"archive\\\") != ARCHIVE:\\n        raise ValueError(\\\"Unrecognized original input identity\\\")\\n    expected = inputs.get(\\\"members\\\")\\n    if not isinstance(expected, dict) or set(expected) != set(MEMBERS):\\n        raise ValueError(\\\"Expected all eight original member identities\\\")\\n    archive = read_regular(archive_path, ARCHIVE[\\\"bytes\\\"])\\n    if pin(archive) != ARCHIVE:\\n        raise ValueError(\\\"The archive is not the exact original qualified ZIP\\\")\\n    payload = {}\\n    with zipfile.ZipFile(io.BytesIO(archive)) as package:\\n        infos = package.infolist()\\n        if len(infos) != 8 or len({item.filename for item in infos}) != 8 or {item.filename for item in infos} != set(MEMBERS):\\n            raise ValueError(\\\"The original package must contain exactly eight unique members\\\")\\n        for name in MEMBERS:\\n            if not isinstance(expected[name], dict):\\n                raise ValueError(\\\"Invalid original member identity: \\\" + name)\\n            rel = PurePosixPath(name)\\n            item = package.getinfo(name)\\n            mode = item.external_attr >> 16\\n            if rel.is_absolute() or \\\"..\\\" in rel.parts or item.is_dir() or item.flag_bits & 1:\\n                raise ValueError(\\\"Unexpected archive path or encrypted member\\\")\\n            if not stat.S_ISREG(mode) or format(mode, \\\"o\\\") != expected[name].get(\\\"zip_mode\\\"):\\n                raise ValueError(\\\"Unexpected original archive mode: \\\" + name)\\n            data = package.read(item)\\n            if pin(data) != {key: expected[name].get(key) for key in ARCHIVE}:\\n                raise ValueError(\\\"Original member identity mismatch: \\\" + name)\\n            payload[\\\"app/\\\" + name] = data\\n    manifest = {}\\n    for line in payload[\\\"app/MANIFEST.sha256\\\"].decode(\\\"ascii\\\").splitlines():\\n        digest, name = line.split(None, 1)\\n        if name in manifest or name == \\\"MANIFEST.sha256\\\" or name not in MEMBERS:\\n            raise ValueError(\\\"Unexpected original checksum entry\\\")\\n        if hashlib.sha256(payload[\\\"app/\\\" + name]).hexdigest() != digest:\\n            raise ValueError(\\\"Original checksum mismatch: \\\" + name)\\n        manifest[name] = digest\\n    if set(manifest) != set(MEMBERS) - {\\\"MANIFEST.sha256\\\"}:\\n        raise ValueError(\\\"Expected all seven original checksum entries\\\")\\n    python = Path(sys.executable).resolve(strict=True)\\n    python_data = read_regular(python, 4 * 1024 * 1024)\\n    runtime = {\\\"configured\\\": sys.executable, \\\"resolved\\\": str(python),\\n               \\\"version\\\": sys.version.split()[0], **pin(python_data)}\\n    template = source_data[\\\"launch.command.in\\\"].decode(\\\"utf-8\\\")\\n    if template.count(\\\"@PYTHON@\\\") != 1 or template.count(\\\"@LAUNCHER@\\\") != 1:\\n        raise ValueError(\\\"Launcher template tokens do not match the source contract\\\")\\n    rendered = template.replace(\\\"@PYTHON@\\\", shlex.quote(str(python))).replace(\\n        \\\"@LAUNCHER@\\\", shlex.quote(str(destination / \\\"launch.py\\\")))\\n    payload[\\\"Open RecallWeave.command\\\"] = rendered.encode(\\\"utf-8\\\")\\n    for name in (\\\"launch.py\\\", \\\"README.md\\\", \\\"INPUTS.json\\\"):\\n        payload[name] = source_data[name]\\n    payload[\\\"recovery/RecallWeave-edit-distance-offline.zip\\\"] = archive\\n    for name, data in source_data.items():\\n        payload[\\\"recovery/source/\\\" + name] = data\\n    modes = {name: 0o700 if name == \\\"Open RecallWeave.command\\\" else 0o444 for name in payload}\\n    guard = admission(owned, destination)\\n    size_before = owned_bytes(owned)\\n    marker = {\\n        \\\"schema\\\": \\\"recall-edit-distance-local-installation/v1\\\", \\\"root\\\": str(destination),\\n        \\\"entry\\\": \\\"app/START-HERE.html\\\", \\\"archive\\\": ARCHIVE, \\\"python\\\": runtime,\\n        \\\"files\\\": {name: {**pin(data), \\\"mode\\\": format(modes[name], \\\"04o\\\")}\\n                  for name, data in sorted(payload.items())},\\n        \\\"source\\\": {name: pin(data) for name, data in sorted(source_data.items())},\\n        \\\"admission\\\": guard, \\\"combined_owned_cap\\\": CAP, \\\"owned_bytes_before\\\": size_before,\\n        \\\"original_byte_policy\\\": \\\"All eight app assets equal the qualified original ZIP; no source rebuild or reader replacement.\\\",\\n        \\\"reader_boundary\\\": \\\"Strict UTF-8 picker and combined-output corrections remain with #7/#181/#109/#159; not installed here.\\\",\\n    }\\n    marker_data = (json.dumps(marker, ensure_ascii=False, indent=2) + \\\"\\\\n\\\").encode(\\\"utf-8\\\")\\n    planned_bytes = sum(len(data) for data in payload.values()) + len(marker_data)\\n    if size_before + planned_bytes > CAP:\\n        raise ValueError(\\\"Combined owned preparation and installation exceeds the 2 MiB cap\\\")\\n    # mkdir is exclusive; failures preserve a newly created partial destination.\\n    destination.mkdir(mode=0o700)\\n    for name, data in payload.items():\\n        write_new(destination / name, data, modes[name])\\n    write_new(destination / \\\"INSTALLATION.json\\\", marker_data, 0o444)\\n    actual = owned_bytes(destination)\\n    if actual != planned_bytes:\\n        raise RuntimeError(\\\"Installation byte count differed after the final marker\\\")\\n    print(json.dumps({\\n        \\\"installed\\\": str(destination), \\\"entry\\\": str(destination / \\\"Open RecallWeave.command\\\"),\\n        \\\"application_entry\\\": str(destination / \\\"app\\\" / \\\"START-HERE.html\\\"),\\n        \\\"files\\\": len(payload) + 1, \\\"installed_bytes\\\": actual,\\n        \\\"combined_owned_bytes\\\": size_before + actual, \\\"marker\\\": pin(marker_data),\\n        \\\"python\\\": runtime, \\\"product_or_browser_invocations\\\": 0,\\n    }, ensure_ascii=False, separators=(\\\",\\\", \\\":\\\")))\\n    return 0\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    try:\\n        raise SystemExit(main())\\n    except (OSError, ValueError, RuntimeError, subprocess.SubprocessError, zipfile.BadZipFile) as error:\\n        print(json.dumps({\\n            \\\"error\\\": str(error),\\n            \\\"partial_destination_policy\\\": \\\"Preserve any newly created partial target; never overwrite or delete an existing installation.\\\",\\n        }, ensure_ascii=False), file=sys.stderr)\\n        raise SystemExit(1)\\n\"},{\"path\":\"launch.py\",\"git_blob\":\"17e7a6f74c543755669151be69a0705b23d9a29e\",\"bytes\":6649,\"uploaded\":true,\"exact_readback\":true,\"content\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Open one verified, unchanged RecallWeave edit-distance installation.\\\"\\\"\\\"\\nimport argparse\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path, PurePosixPath\\nimport stat\\nimport subprocess\\nimport sys\\n\\nARCHIVE = {\\n    \\\"bytes\\\": 53535,\\n    \\\"sha256\\\": \\\"a86d823d70be98d08fd804ce9d8bccdb071b586adf5c30c0784a96a5db2a03e9\\\",\\n    \\\"git_blob\\\": \\\"ae0f3ed4e067fd527b1db7e103270419242db0c2\\\",\\n}\\nMEMBERS = (\\n    \\\"AI-DISCLOSURE.md\\\", \\\"MANIFEST.sha256\\\", \\\"SOURCE-PROVENANCE.json\\\",\\n    \\\"START-HERE.html\\\", \\\"courses/edit-distance-explorer.html\\\",\\n    \\\"courses/edit-distance.json\\\", \\\"courses/edit-distance.md\\\", \\\"demo.html\\\",\\n)\\nSOURCES = (\\\"install.py\\\", \\\"launch.py\\\", \\\"launch.command.in\\\", \\\"README.md\\\", \\\"INPUTS.json\\\")\\nREQUIRED = (\\n    {\\\"Open RecallWeave.command\\\", \\\"launch.py\\\", \\\"README.md\\\", \\\"INPUTS.json\\\",\\n     \\\"recovery/RecallWeave-edit-distance-offline.zip\\\"}\\n    | {\\\"app/\\\" + name for name in MEMBERS}\\n    | {\\\"recovery/source/\\\" + name for name in SOURCES}\\n)\\n\\n\\ndef pin(data):\\n    return {\\n        \\\"bytes\\\": len(data),\\n        \\\"sha256\\\": hashlib.sha256(data).hexdigest(),\\n        \\\"git_blob\\\": hashlib.sha1(b\\\"blob \\\" + str(len(data)).encode(\\\"ascii\\\") + b\\\"\\\\0\\\" + data).hexdigest(),\\n    }\\n\\n\\ndef read_regular(path, limit=1024 * 1024):\\n    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)\\n    with os.fdopen(fd, \\\"rb\\\") as stream:\\n        before = os.fstat(stream.fileno())\\n        if not stat.S_ISREG(before.st_mode) or before.st_size > limit:\\n            raise ValueError(\\\"Expected a bounded regular file: \\\" + str(path))\\n        data = stream.read(limit + 1)\\n        after = os.fstat(stream.fileno())\\n    fields = (\\\"st_dev\\\", \\\"st_ino\\\", \\\"st_size\\\", \\\"st_mtime_ns\\\", \\\"st_ctime_ns\\\")\\n    if len(data) > limit or len(data) != before.st_size or any(\\n        getattr(before, key) != getattr(after, key) for key in fields\\n    ):\\n        raise ValueError(\\\"File changed while reading: \\\" + str(path))\\n    return data, stat.S_IMODE(before.st_mode)\\n\\n\\ndef installed_file(root, relative):\\n    rel = PurePosixPath(relative)\\n    if rel.is_absolute() or \\\"..\\\" in rel.parts or not rel.parts:\\n        raise ValueError(\\\"Invalid installed path\\\")\\n    current = root\\n    for part in rel.parts[:-1]:\\n        current = current / part\\n        if current.is_symlink() or not current.is_dir():\\n            raise ValueError(\\\"Expected an unchanged installed directory: \\\" + str(current))\\n    return root.joinpath(*rel.parts)\\n\\n\\ndef verify(root):\\n    if root.is_symlink() or not root.is_dir():\\n        raise ValueError(\\\"Expected the original installation directory\\\")\\n    raw, _ = read_regular(root / \\\"INSTALLATION.json\\\", 65536)\\n    marker = json.loads(raw)\\n    if not isinstance(marker, dict) or marker.get(\\\"schema\\\") != \\\"recall-edit-distance-local-installation/v1\\\":\\n        raise ValueError(\\\"Unrecognized installation marker\\\")\\n    if marker.get(\\\"root\\\") != str(root) or marker.get(\\\"archive\\\") != ARCHIVE:\\n        raise ValueError(\\\"Installation identity does not match this location\\\")\\n    runtime = marker.get(\\\"python\\\")\\n    python = Path(sys.executable).resolve(strict=True)\\n    runtime_data, _ = read_regular(python, 4 * 1024 * 1024)\\n    if not isinstance(runtime, dict) or runtime.get(\\\"resolved\\\") != str(python) or runtime.get(\\\"version\\\") != sys.version.split()[0]:\\n        raise ValueError(\\\"The recorded Python runtime is no longer selected\\\")\\n    if pin(runtime_data) != {key: runtime.get(key) for key in ARCHIVE}:\\n        raise ValueError(\\\"The recorded Python runtime bytes changed\\\")\\n    files = marker.get(\\\"files\\\")\\n    if not isinstance(files, dict) or set(files) != REQUIRED:\\n        raise ValueError(\\\"Installation manifest does not describe the complete package\\\")\\n    for relative, expected in files.items():\\n        if not isinstance(expected, dict) or set(expected) != {\\\"bytes\\\", \\\"sha256\\\", \\\"git_blob\\\", \\\"mode\\\"}:\\n            raise ValueError(\\\"Invalid installed file identity: \\\" + relative)\\n        data, mode = read_regular(installed_file(root, relative))\\n        if pin(data) != {key: expected.get(key) for key in ARCHIVE}:\\n            raise ValueError(\\\"Installed file changed: \\\" + relative)\\n        if format(mode, \\\"04o\\\") != expected.get(\\\"mode\\\"):\\n            raise ValueError(\\\"Installed permissions changed: \\\" + relative)\\n    recovered, _ = read_regular(installed_file(root, \\\"recovery/RecallWeave-edit-distance-offline.zip\\\"))\\n    if pin(recovered) != ARCHIVE:\\n        raise ValueError(\\\"The original recovery archive changed\\\")\\n    inputs_raw, _ = read_regular(root / \\\"INPUTS.json\\\")\\n    inputs = json.loads(inputs_raw)\\n    if not isinstance(inputs, dict) or inputs.get(\\\"archive\\\") != ARCHIVE or not isinstance(inputs.get(\\\"members\\\"), dict) or set(inputs[\\\"members\\\"]) != set(MEMBERS):\\n        raise ValueError(\\\"Original input identities changed\\\")\\n    for name in MEMBERS:\\n        if not isinstance(inputs[\\\"members\\\"][name], dict):\\n            raise ValueError(\\\"Invalid original member identity: \\\" + name)\\n        data, _ = read_regular(installed_file(root, \\\"app/\\\" + name))\\n        if pin(data) != {key: inputs[\\\"members\\\"][name].get(key) for key in ARCHIVE}:\\n            raise ValueError(\\\"Original application file changed: \\\" + name)\\n    return marker, pin(raw)\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=\\\"Open the verified local edit-distance package.\\\")\\n    parser.add_argument(\\\"--no-open\\\", action=\\\"store_true\\\",\\n                        help=\\\"Report the verified local entry without requesting a browser.\\\")\\n    args = parser.parse_args()\\n    root = Path(os.path.abspath(__file__)).parent\\n    _, marker_pin = verify(root)\\n    entry = root / \\\"app\\\" / \\\"START-HERE.html\\\"\\n    result = {\\n        \\\"installation\\\": str(root), \\\"entry\\\": str(entry), \\\"entry_uri\\\": entry.as_uri(),\\n        \\\"marker\\\": marker_pin, \\\"original_archive\\\": ARCHIVE, \\\"opened\\\": False,\\n    }\\n    if not args.no_open:\\n        opened = subprocess.run(\\n            [\\\"/usr/bin/open\\\", entry.as_uri()], capture_output=True, text=True, timeout=10\\n        )\\n        if opened.returncode != 0:\\n            raise RuntimeError(\\\"The macOS file opener refused the entry: \\\" + opened.stderr[:4096].strip())\\n        result[\\\"opened\\\"] = True\\n        result[\\\"open_status\\\"] = \\\"macOS accepted the request; this is not a browser-use receipt\\\"\\n    if args.no_open:\\n        print(json.dumps(result, ensure_ascii=False, separators=(\\\",\\\", \\\":\\\")))\\n    else:\\n        print(\\\"RecallWeave is opening in your browser. Keep your study notes before closing the lesson.\\\")\\n    return 0\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    try:\\n        raise SystemExit(main())\\n    except (OSError, ValueError, RuntimeError, subprocess.SubprocessError) as error:\\n        print(json.dumps({\\\"error\\\": str(error)}, ensure_ascii=False), file=sys.stderr)\\n        raise SystemExit(1)\\n\"},{\"path\":\"launch.command.in\",\"git_blob\":\"1e095b1ef54589a4adca241a92eaa352ef9584db\",\"bytes\":54,\"uploaded\":true,\"exact_readback\":true,\"content\":\"#!/bin/sh\\nset -eu\\nexec @PYTHON@ -I -B @LAUNCHER@ \\\"$@\\\"\\n\"},{\"path\":\"INPUTS.json\",\"git_blob\":\"f803e8ff51909d7ccade1158c6616d06f712c010\",\"bytes\":2934,\"uploaded\":true,\"exact_readback\":true,\"content\":\"{\\n  \\\"schema\\\": \\\"recall-edit-distance-local-inputs/v1\\\",\\n  \\\"repository\\\": \\\"Jacob-Met/RecallWeave\\\",\\n  \\\"delivery_commit\\\": \\\"cb2f0ad1bc59bac7541004cde174179923e6cb75\\\",\\n  \\\"delivery_tree\\\": \\\"8514ed3862142f5c3daf9c889b215ad3edb074f8\\\",\\n  \\\"source_commit\\\": \\\"cb0b0ac9e2badfea135aec3b8d021cb997b5831b\\\",\\n  \\\"original_receiving_commit\\\": \\\"65138e04d175102fb8b1175a4c05cf95b133009c\\\",\\n  \\\"archive\\\": {\\n    \\\"bytes\\\": 53535,\\n    \\\"sha256\\\": \\\"a86d823d70be98d08fd804ce9d8bccdb071b586adf5c30c0784a96a5db2a03e9\\\",\\n    \\\"git_blob\\\": \\\"ae0f3ed4e067fd527b1db7e103270419242db0c2\\\"\\n  },\\n  \\\"carrier\\\": {\\n    \\\"bytes\\\": 71380,\\n    \\\"sha256\\\": \\\"48a772124737ebe5ff2eab773e6e6b10da2675619bbff0c05173f8598a0667fa\\\",\\n    \\\"git_blob\\\": \\\"0f984d3f82104f4a309b1a17b908b159477c93e9\\\"\\n  },\\n  \\\"members\\\": {\\n    \\\"AI-DISCLOSURE.md\\\": {\\n      \\\"bytes\\\": 578,\\n      \\\"sha256\\\": \\\"f3a9b47aeee8b8f353632012d6816cbb9d24bddbf04358a8d2fc0921ce75796a\\\",\\n      \\\"git_blob\\\": \\\"a7c78b66d3d366a80108cb7650f894d293d70fa7\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    },\\n    \\\"MANIFEST.sha256\\\": {\\n      \\\"bytes\\\": 616,\\n      \\\"sha256\\\": \\\"c0ef6bb1aa105024fa47800701e7a5409e8b3acda7a6ef66d789ff932735aea1\\\",\\n      \\\"git_blob\\\": \\\"654a200ea39ea1dc9f161ead8d9ed2d02ec2835c\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    },\\n    \\\"SOURCE-PROVENANCE.json\\\": {\\n      \\\"bytes\\\": 3224,\\n      \\\"sha256\\\": \\\"e8209402ceddb7f674daf2461942ea71c758cb6f4472be9889cebb5ba13b5aa4\\\",\\n      \\\"git_blob\\\": \\\"4243f30417e5fbe6d2142c8dc417790386db02bf\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    },\\n    \\\"START-HERE.html\\\": {\\n      \\\"bytes\\\": 3625,\\n      \\\"sha256\\\": \\\"be0548a518d3841ddc90351453f58bbb07a0702f7d2a01533ad4fd7e0738ed57\\\",\\n      \\\"git_blob\\\": \\\"9f2be3e41696f02c05b38166e08f7ceffb7d4302\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    },\\n    \\\"courses/edit-distance-explorer.html\\\": {\\n      \\\"bytes\\\": 47877,\\n      \\\"sha256\\\": \\\"eff706073ff25346d0b88e3f292ffcf02158db147f9f4dae0e18d1e08e2f3a01\\\",\\n      \\\"git_blob\\\": \\\"e358cedae9a3b7f14ecb2d341faa3417f75d0cff\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    },\\n    \\\"courses/edit-distance.json\\\": {\\n      \\\"bytes\\\": 11066,\\n      \\\"sha256\\\": \\\"753499d3f6909d46d7628a5cabd85f2f5d2f94e9719d58313cbf13d73374df99\\\",\\n      \\\"git_blob\\\": \\\"df3aaf73eac33ce64ca7efd098a200385749a70e\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    },\\n    \\\"courses/edit-distance.md\\\": {\\n      \\\"bytes\\\": 9713,\\n      \\\"sha256\\\": \\\"e48e2bbb2bad6f05cca0c64b8714d19f36b99de701555e019de283fb80a25a57\\\",\\n      \\\"git_blob\\\": \\\"249bd1dfc7b4156f6d4496465afc10439c6bca24\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    },\\n    \\\"demo.html\\\": {\\n      \\\"bytes\\\": 98468,\\n      \\\"sha256\\\": \\\"fe7d44d125f9797c867251c05f02868a7cacf91c7d5129f46bbca3c69dc7ae1d\\\",\\n      \\\"git_blob\\\": \\\"ef7bc3e27e7f161d917ced6a457fad8822802f3f\\\",\\n      \\\"zip_mode\\\": \\\"100644\\\"\\n    }\\n  },\\n  \\\"source_owner\\\": \\\"cf5799f6d38b\\\",\\n  \\\"reservation\\\": \\\"https://github.com/Jacob-Met/RecallWeave/issues/140#issuecomment-6076471572\\\",\\n  \\\"reader_boundary\\\": \\\"Original demo ef7bc3e remains unchanged. This package does not include the strict UTF-8 picker replacement be645943; #7/#181/#109/#159 retain its source and combined-output integration.\\\"\\n}\\n\"},{\"path\":\"README.md\",\"git_blob\":\"34a644e01de4a9435a9f5d763b1aec32574a9d72\",\"bytes\":5615,\"uploaded\":true,\"exact_readback\":true,\"content\":\"# RecallWeave edit-distance local installation\\n\\nThis installation keeps the exact qualified eight-file edit-distance package in one stable Mac folder. It includes the offline explorer, twelve-question lesson, worked guide, original RecallWeave learner and original attribution. The original ZIP and the installation source are retained for recovery.\\n\\n## Learn and keep your notes\\n\\nOpen **Open RecallWeave.command** in:\\n\\n`/Users/me/Applications/RecallWeaveEditDistance-c945953fdeb7`\\n\\nThe launcher verifies the installed package and asks the existing macOS file opener to open `app/START-HERE.html`. The included activities require no account, server or network connection. Optional academic/source links are external reading.\\n\\n1. In START-HERE, choose **Open the unchanged RecallWeave learner**. Its initial bundled lesson is biology.\\n2. Under **Bring your own lesson**, select **Choose a deck file** and choose `app/courses/edit-distance.json` inside this installation. Review the preview, then choose **Start this deck**. This replaces the current lesson in that tab.\\n3. Answer the twelve questions and read the review. You can write your own explanations and application response.\\n4. Choose **Download study notes** before closing or refreshing. Keep the downloaded `recallweave-study-notes-YYYY-MM-DD.txt` in your chosen document/download location.\\n\\nThe notes are a readable record of the questions, first answers, explanations, writing and any practice. They do not restore an editable session after a refresh. No automatic persistence or writing-restoration feature is added by this installation. The existing explorer remains available from START-HERE; its original input policy and guide explain what its minimum-cost alignment means.\\n\\n## Installed version and input boundary\\n\\nAll eight files under `app/` have the exact bytes from the original 53,535-byte ZIP:\\n\\n- Delivery commit `cb2f0ad1bc59bac7541004cde174179923e6cb75`; tree `8514ed3862142f5c3daf9c889b215ad3edb074f8`.\\n- Original ZIP Git `ae0f3ed4e067fd527b1db7e103270419242db0c2`.\\n- ZIP SHA256 `a86d823d70be98d08fd804ce9d8bccdb071b586adf5c30c0784a96a5db2a03e9`.\\n- Original learner Git `ef7bc3e27e7f161d917ced6a457fad8822802f3f`, 98,468 bytes.\\n\\nThe included course is the exact checked original. The separate strict UTF-8 picker replacement `be645943c6f5ad2357851b3f4f65050dfec8e6db` is not included; this installation retains the original selected-file behavior. The #7/#181 picker and #109/#159 combined-output owners retain that correction and its integration. This package does not claim corrected handling of damaged external UTF-8 decks, combined-pack integration or unfinished-session resume acceptance.\\n\\n[Original source qualification](https://github.com/Jacob-Met/RecallWeave/issues/140#issuecomment-6072029542), [original offline delivery](https://github.com/Jacob-Met/RecallWeave/issues/140#issuecomment-6072607298), and the [distinct installation reservation](https://github.com/Jacob-Met/RecallWeave/issues/140#issuecomment-6076471572) retain the source and ownership history. Existing course, math and browser qualification is reused; it is not repeated by the installer.\\n\\n## Identity and recovery\\n\\n`INSTALLATION.json` records the exact installed files and modes, original archive, source inputs and existing Python runtime. Application and recovery files are read-only; the launcher is executable. The launcher verifies every declared package file before requesting the browser. Ordinary extra files, such as a user's separately saved notes or Finder metadata, are not treated as application inputs.\\n\\nThe launcher uses the existing resolved Python interpreter with its isolated/no-bytecode options. It does not install a runtime, register a package binary, alter PATH, add a launch agent or start a server. Its `--no-open` option reports the verified file path, URI and marker identity without requesting a browser. That mode supports explicit inspection and private-browser receiving; it does not establish Finder/default-profile acceptance.\\n\\nThe original ZIP is retained at `recovery/RecallWeave-edit-distance-offline.zip`. All five installer/launcher/guide/input files are retained at `recovery/source/`. If recovery is needed, choose a new, absent destination and run the retained installer with the existing Python interpreter, for example:\\n\\n```sh\\n/Library/Frameworks/Python.framework/Versions/3.13/bin/python3 \\\\\\n  /Users/me/Applications/RecallWeaveEditDistance-c945953fdeb7/recovery/source/install.py \\\\\\n  --archive /Users/me/Applications/RecallWeaveEditDistance-c945953fdeb7/recovery/RecallWeave-edit-distance-offline.zip \\\\\\n  --destination /Users/me/Applications/RecallWeaveEditDistance-recovered-c945953fdeb7 \\\\\\n  --owned-root /Users/me/Applications/RecallWeaveEditDistance-c945953fdeb7\\n```\\n\\nThat additional recovery installation has not been executed. The installer refuses any existing destination and preserves a newly created partial destination on failure. It validates the complete exact original ZIP, all member identities and original checksums, copies the source inputs, and writes the final marker last. It requires at least 256 MiB free disk and 2 GiB conservative available RAM, with a combined 2 MiB allocation for the declared owned preparation directory and new installation. It does not remove another version to make room.\\n\\nThis installation has its own unique source/evidence fence. cf5799 retains the original course and delivery; 6c20's original extracted-package receiving stays closed. Other RecallWeave installations and the shared learner, author, catalog, picker and combined-package sources are unchanged.\\n\"}]")
